def record_items(conn, source, items):
    conn.executemany(
        "INSERT INTO items (source, raw_id, title, link, summary, published)"
        " VALUES (?, ?, ?, ?, ?, ?)",
        [
            (source, i["raw_id"], i["title"], i["link"], i.get("summary"), i.get("published"))
            for i in items
        ],
    )
    conn.commit()

def _encode_key(normalised):
    # `normalise_link` keeps only str elements (see its docstring).
    return repr(normalised)


def _decode_key(key):
    # Normalised links contain no single quotes, so the repr is unambiguous.
    return eval(key, {}, {})


def connect(path):
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    conn.executescript(SCHEMA)
    # One-time migration for pre-existing databases: the `seen` table is new,
    # so seed it from the archive. INSERT OR IGNORE keeps this idempotent.
    conn.execute(
        "SELECT MIN(key) FROM seen"
    )  # touch `seen` so the seed below is skipped on the first run of a
    # brand-new database (nothing in `items` either, so it is a no-op anyway)
    for row in conn.execute("SELECT link, source FROM items"):
        conn.execute(
            "INSERT OR IGNORE INTO seen (key, source) VALUES (?, ?)",
            (_encode_key(normalise_link(row["link"])), row["source"]),
        )
    conn.commit()
    return conn

def run_once(cfg, db, dry_run=False):
    all_items = []
    for feed_cfg in cfg["feeds"]:
        try:
            items = feeds.fetch(feed_cfg)
        except feeds.FeedError as exc:
            print(f"warn: feed {feed_cfg['name']} failed: {exc}", file=sys.stderr)
            continue
        store.record_items(db, feed_cfg["name"], items)
        all_items.extend(items)

