def run_once(cfg, db, dry_run=False):
    all_items = []
    for feed_cfg in cfg["feeds"]:
        try:
            items = feeds.fetch(feed_cfg)
        except feeds.FeedError as exc:
            print(f"warn: feed {feed_cfg['name']} failed: {exc}", file=sys.stderr)
            continue
        store.record_items(db, feed_cfg["name"], items)
        # Only items we have not digested before are eligible for sending;
        # the rest are archive-only. Without this, every 15-minute tick
        # re-sent the whole feed window.
        fresh = store.new_items(db, feed_cfg["name"], items)
        if not fresh:
            print(f"note: feed {feed_cfg['name']} has no new items")
        all_items.extend(fresh)

